import { AbsoluteFill, OffthreadVideo, interpolate, staticFile, useCurrentFrame } from "remotion";

/**
 * Every scene outlives its narration by the tail padding, but a presenter
 * CLIP ends with the narration — without a fade, her last frame freezes
 * on screen for the padding before the cut (owner note at the v2 gate).
 * Dipping to black over the clip's final moments reads as a deliberate
 * beat, and the following scene rises out of the same dark register.
 */
const FADE_FRAMES = 14;

/**
 * Full-screen presenter scene: the HeyGen clip generated by
 * scripts/presenter.mjs for this scene id. The clip's audio IS the scene's
 * narration (it was lip-synced from the narration MP3), so no separate
 * narration track is mounted for presenter scenes. `clipFrames` (from the
 * narration manifest — the clip is lip-synced to that audio) anchors the
 * exit dip; without it the clip plays plain.
 */
export const PresenterScene = ({
  sceneId,
  clipFrames,
}: {
  sceneId: string;
  clipFrames?: number;
}) => {
  const frame = useCurrentFrame();
  const opacity =
    clipFrames === undefined
      ? 1
      : interpolate(frame, [clipFrames - 4, clipFrames - 4 + FADE_FRAMES], [1, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
  return (
    <AbsoluteFill style={{ background: "#000" }}>
      <AbsoluteFill style={{ opacity }}>
        <OffthreadVideo src={staticFile(`presenter/${sceneId}.mp4`)} />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};
